-- Apply through Supabase CLI. No public signup grants membership.
create extension if not exists pgcrypto;
create table public.tenants(id uuid primary key default gen_random_uuid(),name text not null,code text not null unique,color text not null default '#0e9488');
create table public.memberships(tenant_id uuid references public.tenants on delete cascade,user_id uuid references auth.users on delete cascade,role text not null check(role in('admin','controller','customer_admin','customer_viewer')),primary key(tenant_id,user_id));
create function public.has_tenant(t uuid,write_access boolean default false,controller_access boolean default false) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from memberships where tenant_id=t and user_id=auth.uid() and (not write_access or role<>'customer_viewer') and (not controller_access or role in('admin','controller'))); $$;
revoke all on function public.has_tenant(uuid,boolean,boolean) from public; grant execute on function public.has_tenant(uuid,boolean,boolean) to authenticated;
create table public.drivers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,name text not null,phone text not null,licence_expiry date,prdp_expiry date,unique(tenant_id,id));
create table public.vehicles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,fleet_no text not null,horse_reg text not null,trailer_one text not null default '',trailer_two text not null default '',driver_id uuid,load_status text not null default 'Empty' check(load_status in('Loaded','Empty')),provider text not null default 'Unconnected',location text not null default 'No confirmed GPS',lat double precision,lng double precision,gps_at timestamptz,simulated boolean not null default false,speed double precision,unique(tenant_id,id),unique(tenant_id,fleet_no),foreign key(tenant_id,driver_id) references drivers(tenant_id,id));
create table public.jobs(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,reference text not null default ('MCY-'||substr(gen_random_uuid()::text,1,8)),vehicle_id uuid not null,driver_id uuid,controller text not null default 'Unassigned',loading_code text not null,loading_customer text not null,delivery_code text not null,delivery_customer text not null,cargo text not null,status text not null default 'Created' check(status in('Created','Assigned','Accepted','En Route to Loading','At Loading','Loaded','In Transit','At Delivery','Delivered','POD Received','Closed','Exception','Cancelled')),eta timestamptz,scheduled_at timestamptz not null,destination_lat double precision not null,destination_lng double precision not null,eta_approved boolean not null default false,exception text,unique(tenant_id,id),foreign key(tenant_id,vehicle_id) references vehicles(tenant_id,id),foreign key(tenant_id,driver_id) references drivers(tenant_id,id));
create table public.documents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,name text not null,kind text not null,vehicle_id uuid,job_id uuid,driver_id uuid,expires_at timestamptz,verified boolean not null default false,path text not null,created_at timestamptz not null default now(),foreign key(tenant_id,vehicle_id) references vehicles(tenant_id,id),foreign key(tenant_id,job_id) references jobs(tenant_id,id),foreign key(tenant_id,driver_id) references drivers(tenant_id,id),check(path like tenant_id::text||'/%'));
create table public.alerts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,vehicle_id uuid not null,severity text not null check(severity in('critical','warning','info')),title text not null,detail text not null,acknowledged boolean not null default false,created_at timestamptz not null default now(),foreign key(tenant_id,vehicle_id) references vehicles(tenant_id,id));
create unique index alerts_open_dedupe on alerts(tenant_id,vehicle_id,title) where not acknowledged;
create table public.audit(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,entity_id uuid not null,action text not null,actor text not null,created_at timestamptz not null default now());
create table public.updates(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,vehicle_id uuid not null,text text not null,approved boolean not null default false,created_at timestamptz not null default now(),interval_minutes integer not null check(interval_minutes between 5 and 1440),foreign key(tenant_id,vehicle_id) references vehicles(tenant_id,id));
create table public.tracking_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,vehicle_id uuid not null,provider text not null,event_id text not null,lat double precision not null check(lat between -90 and 90),lng double precision not null check(lng between -180 and 180),speed double precision not null,recorded_at timestamptz not null,unique(tenant_id,provider,event_id),foreign key(tenant_id,vehicle_id) references vehicles(tenant_id,id));
create table public.eta_history(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants,job_id uuid not null,eta timestamptz,provider text not null,created_at timestamptz default now(),foreign key(tenant_id,job_id) references jobs(tenant_id,id));
create function public.audit_change() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into audit(tenant_id,entity_id,action,actor) values(new.tenant_id,new.id,TG_TABLE_NAME||' '||lower(TG_OP),coalesce(auth.uid()::text,'system'));return new;end $$;
create function public.validate_job_transition() returns trigger language plpgsql set search_path=public as $$ declare lifecycle text[]:=array['Created','Assigned','Accepted','En Route to Loading','At Loading','Loaded','In Transit','At Delivery','Delivered','POD Received','Closed'];begin
if new.status<>old.status then
 if old.status in('Closed','Cancelled') then raise exception 'Terminal job';end if;
 if new.status not in('Cancelled','Exception') and (old.status='Exception' or array_position(lifecycle,new.status) is distinct from array_position(lifecycle,old.status)+1) then raise exception 'Invalid lifecycle transition';end if;
 if new.status in('POD Received','Closed') and not exists(select 1 from documents where tenant_id=new.tenant_id and job_id=new.id and kind='Proof of delivery' and verified) then raise exception 'Verified POD required';end if;
end if;return new;end $$;
create trigger job_transition before update on jobs for each row execute function validate_job_transition();
do $$ declare t text;begin foreach t in array array['drivers','vehicles','jobs','documents','alerts','updates','tracking_events','eta_history'] loop execute format('create trigger audit_change after insert or update on public.%I for each row execute function public.audit_change()',t);end loop;end $$;
alter table tenants enable row level security; alter table memberships enable row level security;
create policy tenant_read on tenants for select to authenticated using(public.has_tenant(id));
create policy own_memberships on memberships for select to authenticated using(user_id=auth.uid());
do $$ declare t text;begin foreach t in array array['drivers','vehicles','jobs','documents','alerts','audit','updates','tracking_events','eta_history'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('create policy tenant_read on public.%I for select to authenticated using(public.has_tenant(tenant_id))',t);
end loop;end $$;
-- Sensitive GPS/ETA/audit writes use service worker only. Customer job creation is allowed.
create policy job_create on jobs for insert to authenticated with check(public.has_tenant(tenant_id,true) and status='Created' and eta is null and not eta_approved);
create policy job_dispatch on jobs for update to authenticated using(public.has_tenant(tenant_id,true,true)) with check(public.has_tenant(tenant_id,true,true));
create policy driver_write on drivers for all to authenticated using(public.has_tenant(tenant_id,true,true)) with check(public.has_tenant(tenant_id,true,true));
create policy vehicle_write on vehicles for all to authenticated using(public.has_tenant(tenant_id,true,true)) with check(public.has_tenant(tenant_id,true,true));
create policy document_create on documents for insert to authenticated with check(public.has_tenant(tenant_id,true) and not verified);
create policy document_verify on documents for update to authenticated using(public.has_tenant(tenant_id,true,true)) with check(public.has_tenant(tenant_id,true,true));
create policy alert_ack on alerts for update to authenticated using(public.has_tenant(tenant_id,true,true)) with check(public.has_tenant(tenant_id,true,true));
create policy update_create on updates for insert to authenticated with check(public.has_tenant(tenant_id,true,true) and not approved);
create policy update_approve on updates for update to authenticated using(public.has_tenant(tenant_id,true,true)) with check(public.has_tenant(tenant_id,true,true));
-- Customer readers receive approved ETAs only, even via direct PostgREST access.
revoke select on jobs from authenticated; grant select(id,tenant_id,reference,vehicle_id,driver_id,controller,loading_code,loading_customer,delivery_code,delivery_customer,cargo,status,scheduled_at,destination_lat,destination_lng,exception,eta_approved) on jobs to authenticated;
create view public.visible_jobs with(security_invoker=true) as select id,tenant_id,reference,vehicle_id,driver_id,controller,loading_code,loading_customer,delivery_code,delivery_customer,cargo,status,scheduled_at,destination_lat,destination_lng,exception,eta_approved from jobs;
create function public.approved_etas() returns table(job_id uuid,eta timestamptz) language sql stable security definer set search_path=public as $$ select id,eta from jobs where public.has_tenant(tenant_id) and (eta_approved or public.has_tenant(tenant_id,true,true)); $$;
revoke all on function approved_etas() from public;grant execute on function approved_etas() to authenticated;
-- Private object paths begin with tenant UUID. Signed downloads still require RLS.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('fleet-documents','fleet-documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy doc_upload on storage.objects for insert to authenticated with check(bucket_id='fleet-documents' and public.has_tenant((storage.foldername(name))[1]::uuid,true));
create policy doc_download on storage.objects for select to authenticated using(bucket_id='fleet-documents' and public.has_tenant((storage.foldername(name))[1]::uuid));
create table public.rate_limits(key text primary key,window_start timestamptz not null,hits integer not null);
alter table rate_limits enable row level security;
create function public.consume_rate_limit(bucket_key text,max_requests integer) returns boolean language plpgsql security definer set search_path=public as $$ declare count integer;begin
 if auth.uid() is null or bucket_key not like auth.uid()::text||':%' then return false;end if;
 insert into rate_limits values(bucket_key,date_trunc('minute',now()),1) on conflict(key) do update set hits=case when rate_limits.window_start<date_trunc('minute',now()) then 1 else rate_limits.hits+1 end,window_start=date_trunc('minute',now()) returning hits into count;return count<=least(max_requests,120);end $$;
revoke all on function consume_rate_limit(text,integer) from public;grant execute on function consume_rate_limit(text,integer) to authenticated;
